import type { Teacher } from './teacher-model';

export interface ConceptWeb {
  /**
   * @displayName Concept Web
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Title
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  title: string;
  /**
   * @displayName Description
   */
  description?: string;
  /**
   * @displayName ImageUrl
   */
  imageurl?: string;
  /**
   * @displayName Subject
   */
  subject?: string;
  /**
   * @displayName Teacher Name
   */
  teachername?: Pick<Teacher, 'id' | 'fullname'>;
}

export const _ConceptWeb = 'ConceptWeb' as const;